// ========================================
// PubMed検索URLを組み立てるノード
// ========================================

const config = $input.first().json;

// --- 検索日付範囲の計算 ---
// daysBack日前から今日までを対象にする
const today = new Date();
const fromDate = new Date();
fromDate.setDate(today.getDate() - config.daysBack);

// PubMed APIが求める日付形式: YYYY/MM/DD
const formatDate = (d) => {
  const y = d.getFullYear();
  const m = String(d.getMonth() + 1).padStart(2, '0');
  const day = String(d.getDate()).padStart(2, '0');
  return `${y}/${m}/${day}`;
};

const minDate = formatDate(fromDate);
const maxDate = formatDate(today);

// --- 検索クエリの構築 ---
// テーマが設定されていれば OR で繋げてANDする
let query = config.searchQuery;

// テーマ別絞り込みが必要な場合はここをカスタマイズ
// 現在はベース検索式のみ（全テーマ横断）
// テーマ別に分けたい場合は、themesをループして複数回検索する拡張も可能

// --- esearch APIのURL ---
const esearchUrl = 'https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esearch.fcgi'
  + '?db=pubmed'
  + '&term=' + encodeURIComponent(query)
  + '&retmax=' + config.maxResults
  + '&sort=date'
  + '&datetype=pdat'
  + '&mindate=' + encodeURIComponent(minDate)
  + '&maxdate=' + encodeURIComponent(maxDate)
  + '&retmode=json'
  + ($env.PUBMED_API_KEY ? '&api_key=' + $env.PUBMED_API_KEY : '');

return [{
  json: {
    ...config,
    esearchUrl,
    minDate,
    maxDate
  }
}];

// ========================================
// esearch結果からPMIDリストを取得し、
// efetch用URLを構築するノード
// ========================================

const input = $input.first().json;
const config = $('⚙️ 検索条件・設定').first().json;

// --- esearch結果の解析 ---
const esearchResult = input.esearchresult || input;
const idList = esearchResult.idlist || [];
const count = parseInt(esearchResult.count || '0');

// 結果が0件の場合は空で返す（後続ノードで分岐）
if (idList.length === 0) {
  return [{ json: { pmids: [], count: 0, hasResults: false, config } }];
}

// --- efetch URLの構築 ---
// PMIDをカンマ区切りで結合
const pmidString = idList.join(',');

const efetchUrl = 'https://eutils.ncbi.nlm.nih.gov/entrez/eutils/efetch.fcgi'
  + '?db=pubmed'
  + '&id=' + pmidString
  + '&retmode=xml'
  + ($env.PUBMED_API_KEY ? '&api_key=' + $env.PUBMED_API_KEY : '');

return [{
  json: {
    pmids: idList,
    count: idList.length,
    totalFound: count,
    hasResults: true,
    efetchUrl,
    config
  }
}];

// ========================================
// PubMed XMLを解析して論文データを整形するノード
// - タイトル、要旨、著者、掲載誌、出版日を抽出
// - PubMed URLを生成
// - 重複PMIDを除外
// ========================================

const xmlData = $input.first().json.data || $input.first().json.body || '';
const config = $('⚙️ 検索条件・設定').first().json;

// --- XML文字列から論文情報を抽出する簡易パーサー ---
// n8nのCodeノードではDOMParserが使えないため、正規表現で抽出

function extractBetween(xml, tag) {
  const regex = new RegExp(`<${tag}[^>]*>([\\s\\S]*?)<\\/${tag}>`, 'g');
  const matches = [];
  let match;
  while ((match = regex.exec(xml)) !== null) {
    matches.push(match[1].trim());
  }
  return matches;
}

function extractFirst(xml, tag) {
  const regex = new RegExp(`<${tag}[^>]*>([\\s\\S]*?)<\\/${tag}>`);
  const match = xml.match(regex);
  return match ? match[1].trim() : '';
}

function stripTags(str) {
  return str.replace(/<[^>]+>/g, '').trim();
}

// --- 各論文（PubmedArticle）を分割 ---
const articleBlocks = xmlData.split('<PubmedArticle>');
articleBlocks.shift(); // 最初の空要素を除去

const articles = [];
const seenPmids = new Set();

for (const block of articleBlocks) {
  try {
    // PMID
    const pmid = extractFirst(block, 'PMID');
    if (!pmid || seenPmids.has(pmid)) continue;
    seenPmids.add(pmid);

    // タイトル
    const title = stripTags(extractFirst(block, 'ArticleTitle')) || 'タイトル不明';

    // 要旨（Abstract）
    const abstractBlock = extractFirst(block, 'Abstract');
    const abstractTexts = extractBetween(abstractBlock || '', 'AbstractText');
    const abstract = abstractTexts.map(t => stripTags(t)).join(' ') || 'アブストラクトなし';

    // 著者
    const authorBlock = extractFirst(block, 'AuthorList');
    const lastNames = extractBetween(authorBlock || '', 'LastName');
    const foreNames = extractBetween(authorBlock || '', 'ForeName');
    const authors = lastNames.map((ln, i) => {
      return foreNames[i] ? `${ln} ${foreNames[i]}` : ln;
    }).slice(0, 5); // 最大5名まで表示
    const authorStr = authors.join(', ') + (lastNames.length > 5 ? ' et al.' : '');

    // 掲載誌
    const journal = stripTags(extractFirst(block, 'Title')) || '掲載誌不明';

    // 出版日
    const pubDateBlock = extractFirst(block, 'PubDate');
    const year = extractFirst(pubDateBlock || '', 'Year') || '';
    const month = extractFirst(pubDateBlock || '', 'Month') || '';
    const day = extractFirst(pubDateBlock || '', 'Day') || '';
    const pubDate = [year, month, day].filter(Boolean).join('-') || '日付不明';

    // PubMed URL
    const pubmedUrl = `https://pubmed.ncbi.nlm.nih.gov/${pmid}/`;

    articles.push({
      pmid,
      title,
      abstract,
      authors: authorStr,
      journal,
      pubDate,
      pubmedUrl
    });
  } catch (e) {
    // パースエラーが出ても他の論文の処理を続行
    console.log(`論文パースエラー: ${e.message}`);
  }
}

// 各論文を個別アイテムとして返す（後続のループ処理用）
return articles.map(article => ({ json: { ...article, config } }));

